head.b:skin:
:root {
    --primary-color: #d32f2f;
    --primary-dark: #b71c1c;
    --text-dark: #222222;
    --text-gray: #666666;
    --bg-light: #f9f9f9;
    --border-color: #e0e0e0;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Inter', sans-serif;
}

body {
    background-color: #ffffff;
    color: var(--text-dark);
    line-height: 1.6;
}

a {
    text-decoration: none;
    color: inherit;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 15px;
}

/* --- TOP BAR --- */
.top-bar {
    background: #111111;
    color: #fff;
    font-size: 12px;
    padding: 6px 0;
}

.top-bar-flex {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.social-icons a {
    color: #fff;
    margin-left: 12px;
    transition: color 0.2s;
}

.social-icons a:hover {
    color: var(--primary-color);
}

/* --- HEADER --- */
header {
    background: #ffffff;
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 1000;
}

.main-header {
    padding: 15px 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.header-left {
    display: flex;
    align-items: center;
    gap: 15px;
}

.menu-toggle {
    display: none;
    font-size: 22px;
    background: none;
    border: none;
    cursor: pointer;
    color: var(--text-dark);
}

.logo {
    font-size: 28px;
    font-weight: 800;
    color: var(--primary-color);
    letter-spacing: -1px;
}

.logo span {
    color: #111;
}

.search-box {
    display: flex;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    overflow: hidden;
}

.search-box input {
    padding: 8px 12px;
    border: none;
    outline: none;
    font-size: 14px;
    width: 250px;
}

.search-box button {
    background: var(--primary-color);
    color: white;
    border: none;
    padding: 0 15px;
    cursor: pointer;
}

/* --- NAVIGATION --- */
nav {
    background: var(--primary-color);
}

.nav-container {
    display: flex;
    align-items: center;
}

.nav-links {
    display: flex;
    list-style: none;
    position: relative;
    flex-wrap: wrap;
}

.nav-links li {
    position: relative;
}

.nav-links li a {
    display: flex;
    align-items: center;
    gap: 5px;
    color: white;
    padding: 10px 14px;
    font-size: 13px;
    font-weight: 600;
    white-space: nowrap;
    transition: background 0.2s;
}

.nav-links li a:hover {
    background: var(--primary-dark);
}

/* Dropdown Menu */
.dropdown-menu {
    position: absolute;
    top: 100%;
    left: 0;
    background: #ffffff;
    color: var(--text-dark);
    min-width: 180px;
    box-shadow: 0 8px 16px rgba(0,0,0,0.15);
    border-radius: 0 0 4px 4px;
    list-style: none;
    display: none;
    z-index: 1100;
}

.dropdown-menu.show {
    display: block;
}

.dropdown-menu li a {
    color: var(--text-dark);
    padding: 10px 15px;
    font-weight: 500;
    border-bottom: 1px solid var(--border-color);
}

.dropdown-menu li a:hover {
    background: var(--bg-light);
    color: var(--primary-color);
}

.sidebar-close {
    display: none;
}

.overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0,0,0,0.5);
    display: none;
    z-index: 1500;
}

.overlay.active {
    display: block;
}

/* --- MAIN LAYOUT --- */
.main-container {
    display: grid;
    grid-template-columns: 2.2fr 1fr;
    gap: 30px;
    margin: 30px auto;
}

.category-tag {
    display: inline-block;
    background: var(--primary-color);
    color: white;
    font-size: 11px;
    font-weight: 700;
    padding: 3px 8px;
    border-radius: 3px;
    margin: 12px 0 8px 0;
    text-transform: uppercase;
}

.section-title {
    font-size: 18px;
    font-weight: 700;
    border-left: 4px solid var(--primary-color);
    padding-left: 10px;
    margin: 30px 0 20px 0;
    text-transform: uppercase;
}

.news-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
}

/* FOOTER */
footer {
    background: #111111;
    color: #fff;
    padding: 40px 0 20px 0;
    margin-top: 50px;
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 30px;
    margin-bottom: 30px;
}

.footer-col h3 {
    font-size: 16px;
    margin-bottom: 15px;
    color: var(--primary-color);
}

.footer-col ul {
    list-style: none;
}

.footer-col ul li {
    margin-bottom: 8px;
    font-size: 14px;
    color: #aaa;
}

.footer-col ul li a:hover {
    color: #fff;
}

.copyright {
    text-align: center;
    border-top: 1px solid #222;
    padding-top: 20px;
    font-size: 13px;
    color: #777;
}

@media (max-width: 900px) {
    .menu-toggle { display: block; }
    .main-container { grid-template-columns: 1fr; }
    .nav-links {
        position: fixed;
        top: 0;
        left: -280px;
        width: 280px;
        height: 100vh;
        background: #1a1a1a;
        flex-direction: column;
        padding-top: 60px;
        transition: left 0.3s ease-in-out;
        z-index: 2000;
        overflow-y: auto;
    }
    .nav-links.active { left: 0; }
    .nav-links li a { padding: 15px 20px; border-bottom: 1px solid #333; }
    .sidebar-close {
        display: block !important;
        position: absolute;
        top: 15px;
        right: 20px;
        font-size: 20px;
        color: #fff;
        background: none;
        border: none;
        cursor: pointer;
    }
    .dropdown-menu {
        position: static;
        box-shadow: none;
        background: #252525;
    }
    .footer-grid { grid-template-columns: 1fr; }
}

body.script:
const menuToggle = document.getElementById('menuToggle');
const sidebarClose = document.getElementById('sidebarClose');
const navLinks = document.getElementById('navLinks');
const overlay = document.getElementById('overlay');

if(menuToggle) {
    menuToggle.addEventListener('click', () => {
        navLinks.classList.add('active');
        overlay.classList.add('active');
    });
}

function closeMenu() {
    navLinks.classList.remove('active');
    overlay.classList.remove('active');
}

if(sidebarClose) sidebarClose.addEventListener('click', closeMenu);
if(overlay) overlay.addEventListener('click', closeMenu);

const dropdownToggles = document.querySelectorAll('.dropdown-toggle');
dropdownToggles.forEach(toggle => {
    toggle.addEventListener('click', function(e) {
        e.preventDefault();
        const dropdownMenu = this.nextElementSibling;
        if(dropdownMenu) dropdownMenu.classList.toggle('show');
    });
});
